using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.JournalEntries.Dtos;using Namaa.Domain.Common.Results;namespace Namaa.Application.JournalEntries.Queries.GetJournalEntries;public sealed class GetJournalEntriesQueryHandler(IJournalEntryRepository repository):IRequestHandler<GetJournalEntriesQuery,Result<IReadOnlyList<JournalEntryDto>>>{public async Task<Result<IReadOnlyList<JournalEntryDto>>>Handle(GetJournalEntriesQuery request,CancellationToken cancellationToken)=>Result.Success<IReadOnlyList<JournalEntryDto>>((await repository.GetAllAsync(cancellationToken)).Select(JournalEntryDto.FromEntity).ToList());}
